// 25_ A.1 — the identity tuple, all five components. A raw archive hash alone
// is NOT identity: two tasks may legitimately submit byte-identical artifacts,
// and one task may resubmit with changed routing.
//
// 25_ A.2 — `registration_ref` is minted by the OWNER at
// /owner/artifact/register and travels with the submission. This workflow
// carries it; it cannot mint one, and a submission without one is refused here
// rather than sent on, because the wrapper would refuse it anyway and a local
// refusal is the one that records why.
const crypto = require('crypto');
return items.map(i => {
  const b64 = i.json.artifact_b64 || '';
  const digest = crypto.createHash('sha256')
                       .update(Buffer.from(b64, 'base64')).digest('hex');
  if (!i.json.registration_ref) {
    throw new Error('no registration_ref: the owner must register the artifact '
      + 'at /owner/artifact/register before it can be submitted. The digest '
      + 'computed here is only ever CHECKED AGAINST the owner-registered '
      + 'source_digest — it is never an authority on its own (25_ A.2).');
  }
  return { json: {
    envelope: { trust: 'external-untrusted', partition: 'business' },
    registration_ref: i.json.registration_ref,   // owner-minted (A.2)
    // the five identity components (A.1)
    task_id: i.json.task_id,
    transition: i.json.transition,          // e.g. 'builder->verifier'
    artifact_digest: digest,                // computed here, not trusted
    target_role: i.json.target_role,        // SYMBOLIC role; the wrapper resolves it
    submission_epoch: Number(i.json.submission_epoch ?? 0)
  } };
});
